import {globalIdField} from './core.js?v=20261015-template';
export function defaultUsernameField(meta,role='creator'){const created=role==='creator'&&meta.fields?.find(f=>f.name.toLowerCase()==='created_user'&&f.type==='esriFieldTypeString');if(created)return created.name;const name=meta.editFieldsInfo?.[role==='editor'?'editorField':'creatorField'];return meta.fields?.some(f=>f.name===name)?name:'';}
export function trackingField(meta,role='creator',explicitField){const name=explicitField===undefined?meta.editFieldsInfo?.[role==='editor'?'editorField':'creatorField']:explicitField;if(!name||!meta.fields?.some(f=>f.name===name))throw Error('Choose an existing username field for this layer, such as created_user. The selected '+role+' tracking field is not exposed.');return name;}
export function surveyUsers(meta,features,role,explicitField){const name=trackingField(meta,role,explicitField);return [...new Set(features.map(f=>f.attributes[name]).filter(v=>typeof v==='string'&&v.trim()))].sort();}
export function missingKind(value){return value==null?'NULL':typeof value==='string'&&value.trim()===''?'Blank':'';}
export function surveyIssues(url,meta,features,role,users,required,explicitField){const tracking=trackingField(meta,role,explicitField),gid=globalIdField(meta),selected=users===null?null:new Set(users);const fields=required.map(name=>{const field=meta.fields.find(f=>f.name===name);if(!field)throw Error('Required field no longer exists: '+name);return field;});const issues=[];for(const f of features){const attrs=f.attributes,user=attrs[tracking];if(selected&&!selected.has(user))continue;for(const field of fields){const kind=missingKind(attrs[field.name]);if(kind){const id=attrs[gid?.name]||attrs[meta.objectIdField];issues.push({key:JSON.stringify([url,id,field.name,user]),layer:meta.name,url,user:user||'No tracking username',id,field:field.name,kind});}}}return issues;}
export function newSurveyIssues(issues,previous){return issues.filter(issue=>!previous.has(issue.key));}
export async function loadSurveyRows(api,url,meta,names,progress=()=>{},onUnavailable){
 const oid=meta.objectIdField;if(!oid)throw Error('This layer has no object ID field.');const fields=[...new Set([oid,...names])];if(fields.some(name=>!meta.fields.some(f=>f.name===name)))throw Error('A selected field is not in this layer schema.');
 const ids=await api.ids(url,'1=1'),size=Math.max(1,Math.min(meta.maxRecordCount||500,500)),rows=[];
 async function batch(part){const result=await api.request(url+'/query',{objectIds:part.join(','),outFields:fields.join(','),returnGeometry:false}),features=result.features||[],found=new Map(features.map(f=>[f.attributes[oid],f]));if(result.exceededTransferLimit||part.some(id=>!found.has(id))){if(part.length===1){if(!found.has(part[0])&&onUnavailable){onUnavailable(part[0]);return [];}if(found.has(part[0])&&onUnavailable)return [found.get(part[0])];throw Error('Record '+part[0]+' is inaccessible; reload the layer.');}const mid=Math.floor(part.length/2);return [...await batch(part.slice(0,mid)),...await batch(part.slice(mid))];}return part.map(id=>found.get(id));}
 for(let offset=0;offset<ids.length;offset+=size){rows.push(...await batch(ids.slice(offset,offset+size)));progress(rows.length,ids.length);}return rows;
}
export function parseUsernameList(text){const users=[...new Set(String(text).split(/[\s,;]+/).map(value=>value.trim()).filter(Boolean))];if(!users.length)throw Error('Paste at least one exact username.');if(users.length>1000||users.some(user=>user.length>255))throw Error('Add up to 1,000 usernames, each no longer than 255 characters.');return users;}
export async function loadSurveyUsernames(api,url,meta,field,progress=()=>{}){
 trackingField(meta,'creator',field);let fallbackReason='';
 try{const result=await api.request(url+'/query',{where:'1=1',outFields:field,returnDistinctValues:true,returnGeometry:false});const features=result.features,limit=Number(meta.maxRecordCount)||1000;if(Array.isArray(features)&&features.every(f=>Object.hasOwn(f.attributes||{},field))&&result.exceededTransferLimit!==true&&(result.exceededTransferLimit===false||features.length<limit))return {users:surveyUsers(meta,features,'creator',field),method:'Distinct field values',missingIds:[],recordCount:null,complete:true};fallbackReason='Distinct response was truncated or incomplete.';}catch(error){fallbackReason=error.message;}
 const missingIds=[],rows=await loadSurveyRows(api,url,meta,[field],progress,id=>missingIds.push(id));return {users:surveyUsers(meta,rows,'creator',field),method:'Paged record values',missingIds,recordCount:rows.length,complete:missingIds.length===0,fallbackReason};
}
